#include <iostream>
#include <map>
#include <string>
#include <utility>
using namespace std;

pair<string, int> fetch() { return {"AC", 42}; }

struct Point { int x, y; };

int main() {
    auto [status, score] = fetch();
    cout << "auto [status, score] = fetch();  -> " << status << " / " << score << "\n";

    Point p{3, 4};
    auto& [px, py] = p;      // 绑定到引用才能修改原对象
    px += 10;
    py += 20;
    cout << "引用绑定后修改 -> p = (" << p.x << ", " << p.y << ")\n";

    cout << "遍历 map:\n";
    map<string, int> m{{"cpp", 90}, {"java", 85}};
    for (const auto& [k, v] : m) {
        cout << "  " << k << " = " << v << "\n";
    }
}
